using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
public static class RuinsBalustradeReview{
 static void Check(bool b,string s){if(!b)throw new Exception(s);}
 static Color32[] Shot(Camera c,Vector3 from,Vector3 at,string f){c.transform.position=from;c.transform.LookAt(at);var rt=new RenderTexture(1200,900,24);c.targetTexture=rt;for(int i=0;i<3;i++)c.Render();var prev=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(1200,900,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1200,900),0,0);t.Apply();if(f!=null)File.WriteAllBytes(f,t.EncodeToPNG());var a=t.GetPixels32();RenderTexture.active=prev;c.targetTexture=null;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(t);return a;}
 public static void Run(){const string ev="Evidence/Target51Balustrade";Directory.CreateDirectory(ev);try{
 EditorSceneManager.OpenScene("Assets/RuinsTarget51Output/Room.unity");var root=GameObject.Find("ruins_1").transform.parent.gameObject;var c=UnityEngine.Object.FindAnyObjectByType<Camera>();var sun=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).Single(x=>x.type==LightType.Directional);sun.transform.rotation=Quaternion.Euler(38,-28,0);RenderSettings.ambientLight=Color.gray*.65f;c.orthographic=false;c.backgroundColor=new Color(.075f,.085f,.1f);var from=new Vector3(15,20,21);var at=new Vector3(0,3.5f,0);
 var pixels=Shot(c,from,at,ev+"/room.png");UnityEngine.Object.DestroyImmediate(root);root=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RuinsTarget51Output/Structures/Ruins.prefab"));Check(pixels.SequenceEqual(Shot(c,from,at,null)),"Prefab pixels");EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/RuinsTarget51Output/BalustradePersistence.unity");EditorSceneManager.NewScene(NewSceneSetup.EmptyScene);EditorSceneManager.OpenScene("Assets/RuinsTarget51Output/BalustradePersistence.unity");root=GameObject.Find("ruins_1").transform.parent.gameObject;c=UnityEngine.Object.FindAnyObjectByType<Camera>();sun=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).Single(x=>x.type==LightType.Directional);Check(pixels.SequenceEqual(Shot(c,from,at,null)),"Scene pixels");
 var old=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RuinsTarget49Output/Structures/Ruins.prefab"));int unchanged=0;foreach(Transform t in old.transform){if(!t.name.StartsWith("ruins_"))continue;var a=t.GetComponent<MeshFilter>().sharedMesh;var b=root.transform.Find(t.name).GetComponent<MeshFilter>().sharedMesh;Check(a.vertices.SequenceEqual(b.vertices)&&a.normals.SequenceEqual(b.normals)&&a.uv.SequenceEqual(b.uv)&&a.triangles.SequenceEqual(b.triangles),"Old geometry "+t.name);Check(root.transform.Find(t.name).GetComponent<MeshCollider>().sharedMesh==b,"Old Collider identity");unchanged++;}Check(unchanged==53,"Old count");
 // The new test platform intentionally changes terrain holes. Exclude both
 // terrain/caps from the old-part pixel comparison, while preserving mesh checks.
 foreach(var t in UnityEngine.Object.FindObjectsByType<Terrain>(FindObjectsSortMode.None))t.gameObject.SetActive(false);foreach(var o in new[]{old,root}){var caps=o.transform.Find("TerrainCaps");if(caps)caps.gameObject.SetActive(false);}foreach(int id in new[]{54,55,56})root.transform.Find("ruins_"+id).gameObject.SetActive(false);root.SetActive(false);var before=Shot(c,from,at,null);old.SetActive(false);root.SetActive(true);Check(before.SequenceEqual(Shot(c,from,at,null)),"Old part pixels");UnityEngine.Object.DestroyImmediate(old);
 foreach(Transform t in root.transform)t.gameObject.SetActive(new[]{"ruins_54","ruins_55","ruins_56"}.Contains(t.name));c.orthographic=true;var centre=new Vector3(5,4.1f,10.5f);
 foreach(string view in new[]{"normal","close","opposite","rear"}){sun.transform.rotation=view=="opposite"?Quaternion.Euler(27,130,0):Quaternion.Euler(38,-28,0);c.orthographicSize=view=="normal"?3.8f:2.1f;Shot(c,centre+new Vector3(view=="rear"?-3:2.5f,3.2f,view=="rear"?-6:6),centre,ev+"/balustrade-"+view+".png");}
 sun.transform.rotation=Quaternion.Euler(38,-28,0);root.transform.Find("ruins_55").gameObject.SetActive(false);var obj=root.transform.Find("ruins_56").gameObject;var mr=obj.GetComponent<MeshRenderer>();var mf=obj.GetComponent<MeshFilter>();var saved=mf.sharedMesh;var mat=mr.sharedMaterial;c.orthographicSize=1.35f;centre=new Vector3(6,4.1f,10.5f);Shot(c,centre+new Vector3(1.6f,1.8f,5),centre,ev+"/carved.png");mf.sharedMesh=root.transform.Find("ruins_55").GetComponent<MeshFilter>().sharedMesh;mr.sharedMaterial=root.transform.Find("ruins_55").GetComponent<MeshRenderer>().sharedMaterial;Shot(c,centre+new Vector3(1.6f,1.8f,5),centre,ev+"/plain.png");mf.sharedMesh=saved;mr.sharedMaterial=mat;
 var previous=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RuinsTarget50Output/Structures/Ruins.prefab").transform.Find("ruins_56").GetComponent<MeshFilter>().sharedMesh;
 Check(saved.vertices.SequenceEqual(previous.vertices)&&saved.normals.SequenceEqual(previous.normals)&&saved.triangles.SequenceEqual(previous.triangles),"Geometry changed by ornament");
 Check(!saved.uv.SequenceEqual(previous.uv),"Ornament not updated");
 Shot(c,centre+new Vector3(1.6f,1.8f,5),centre,ev+"/after-close.png");mf.sharedMesh=previous;Shot(c,centre+new Vector3(1.6f,1.8f,5),centre,ev+"/before-close.png");
 c.orthographicSize=3.8f;Shot(c,centre+new Vector3(2.5f,3.2f,6),centre,ev+"/before-normal.png");mf.sharedMesh=saved;Shot(c,centre+new Vector3(2.5f,3.2f,6),centre,ev+"/after-normal.png");
 mf.sharedMesh=root.transform.Find("ruins_55").GetComponent<MeshFilter>().sharedMesh;mr.sharedMaterial=root.transform.Find("ruins_55").GetComponent<MeshRenderer>().sharedMaterial;Shot(c,centre+new Vector3(2.5f,3.2f,6),centre,ev+"/plain-normal.png");mf.sharedMesh=saved;mr.sharedMaterial=mat;

 foreach(Transform t in root.transform)t.gameObject.SetActive(true);Physics.SyncTransforms();int voids=0,posts=0,walkers=0;foreach(int id in new[]{55,56}){var col=root.transform.Find("ruins_"+id).GetComponent<MeshCollider>();float x=id==55?4:6;Check(col.sharedMesh==col.GetComponent<MeshFilter>().sharedMesh,"Collider identity");foreach(float dx in new[]{-.585f,0,.585f}){Check(!col.Raycast(new Ray(new Vector3(x+dx,4.1f,11.5f),Vector3.back),out var hit,2),"Void blocked");voids++;}foreach(float dx in new[]{-.9f,-.3f,.3f,.9f}){Check(col.Raycast(new Ray(new Vector3(x+dx,4.1f,11.5f),Vector3.back),out var hit,2),"Post missing");posts++;}
 foreach(float dx in new[]{-.585f,0,.585f}){var walker=new GameObject("GuardWalker");var cc=walker.AddComponent<CharacterController>();cc.height=1.6f;cc.center=new Vector3(0,.8f,0);cc.radius=.25f;cc.skinWidth=.015f;cc.stepOffset=.25f;walker.transform.position=new Vector3(x+dx,3.63f,11.25f);Physics.SyncTransforms();for(int k=0;k<40;k++)cc.Move(new Vector3(0,-.025f,-.05f));Check(walker.transform.position.z>10.9f,"Guard crossed");UnityEngine.Object.DestroyImmediate(walker);walkers++;}
 foreach(int count in new[]{9,225}){var clones=Enumerable.Range(0,count).Select(k=>{var o=UnityEngine.Object.Instantiate(col.gameObject);o.transform.position=new Vector3(100+k*5,0,100);return o;}).ToArray();Check(clones.Select(o=>o.GetComponent<MeshFilter>().sharedMesh).Distinct().Count()==1&&clones.Select(o=>o.GetComponent<MeshRenderer>().sharedMaterial).Distinct().Count()==1,"Shared references");foreach(var o in clones)UnityEngine.Object.DestroyImmediate(o);}}
 int joints=0;foreach(float dx in new[]{-.003f,0,.003f})for(float y=3.65f;y<4.65f;y+=.08f){Check(Physics.Raycast(new Ray(new Vector3(5+dx,y,11.5f),Vector3.back),out var hit,1.3f)&&hit.collider.name.StartsWith("ruins_"),"Joint gap");joints++;}
 Check(!ShaderUtil.ShaderHasError(mat.shader),"Shader");File.WriteAllText(ev+"/result.json","{\"pass\":true,\"oldMeshes\":53,\"prefabScenePixelDelta\":0,\"oldPartPixelDeltaExcludingTerrain\":0,\"voidRays\":"+voids+",\"postRays\":"+posts+",\"capsuleBlocked\":"+walkers+",\"jointRays\":"+joints+",\"shared9And225Offscreen\":true,\"GPUmeasured\":false}");EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(ev+"/failure.txt",e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
}
